<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
require_role('student');
$userId = (int)current_user()['id'];
$profileStatement = db()->prepare('SELECT u.first_name, u.last_name, u.email, p.total_xp, p.level, p.current_streak, p.longest_streak FROM users u INNER JOIN student_profiles p ON p.user_id = u.id WHERE u.id = :user_id');
$profileStatement->execute(['user_id' => $userId]);
$profile = $profileStatement->fetch();
$achievements = db()->prepare('SELECT a.name, a.description, sa.completed_at FROM student_achievements sa INNER JOIN achievements a ON a.id = sa.achievement_id WHERE sa.user_id = :user_id ORDER BY sa.completed_at DESC'); $achievements->execute(['user_id' => $userId]); $achievements = $achievements->fetchAll();
$badges = db()->prepare('SELECT b.name, b.description, sb.awarded_at FROM student_badges sb INNER JOIN badges b ON b.id = sb.badge_id WHERE sb.user_id = :user_id ORDER BY sb.awarded_at DESC'); $badges->execute(['user_id' => $userId]); $badges = $badges->fetchAll();
$courses = db()->prepare("SELECT c.id, c.title, COUNT(DISTINCT l.id) AS total_lessons, COUNT(DISTINCT lp.id) AS completed_lessons FROM enrollments e INNER JOIN courses c ON c.id = e.course_id LEFT JOIN lessons l ON l.course_id = c.id AND l.status = 'published' LEFT JOIN lesson_progress lp ON lp.lesson_id = l.id AND lp.user_id = e.user_id WHERE e.user_id = :user_id GROUP BY c.id, c.title ORDER BY c.title"); $courses->execute(['user_id' => $userId]); $courses = $courses->fetchAll();
$pageTitle = 'My profile'; require __DIR__ . '/../includes/header.php';
?>
<div class="py-4"><div class="card mb-4"><div class="card-body p-4 p-md-5"><h1 class="h2 fw-bold"><?= e($profile['first_name'] . ' ' . $profile['last_name']) ?></h1><p class="text-secondary mb-4"><?= e($profile['email']) ?></p><div class="row g-4"><div class="col-6 col-md-3"><span class="text-secondary d-block">Level</span><strong class="h3"> <?= (int)$profile['level'] ?></strong></div><div class="col-6 col-md-3"><span class="text-secondary d-block">XP</span><strong class="h3"> <?= (int)$profile['total_xp'] ?></strong></div><div class="col-6 col-md-3"><span class="text-secondary d-block">Current streak</span><strong class="h3"> <?= (int)$profile['current_streak'] ?></strong></div><div class="col-6 col-md-3"><span class="text-secondary d-block">Longest streak</span><strong class="h3"> <?= (int)$profile['longest_streak'] ?></strong></div></div></div></div><div class="row g-4"><div class="col-lg-6"><div class="card h-100"><div class="card-body"><h2 class="h5">Achievements</h2><?php if (!$achievements): ?><p class="text-secondary">Complete lessons and quizzes to unlock achievements.</p><?php else: ?><div class="list-group list-group-flush"> <?php foreach ($achievements as $achievement): ?><div class="list-group-item px-0"><strong><?= e($achievement['name']) ?></strong><div class="small text-secondary"><?= e($achievement['description']) ?></div></div><?php endforeach; ?></div><?php endif; ?></div></div></div><div class="col-lg-6"><div class="card h-100"><div class="card-body"><h2 class="h5">Badges</h2><?php if (!$badges): ?><p class="text-secondary">Your earned badges will appear here.</p><?php else: ?><div class="d-flex flex-wrap gap-2"><?php foreach ($badges as $badge): ?><span class="badge text-bg-primary p-2" title="<?= e($badge['description']) ?>"><?= e($badge['name']) ?></span><?php endforeach; ?></div><?php endif; ?></div></div></div></div><div class="card mt-4"><div class="card-body"><h2 class="h5">Course progress</h2><?php if (!$courses): ?><p class="text-secondary mb-0">You are not enrolled in any courses.</p><?php endif; ?><?php foreach ($courses as $course): $total = (int)$course['total_lessons']; $completed = (int)$course['completed_lessons']; $progress = $total ? (int)round($completed / $total * 100) : 0; ?><div class="mb-3"><div class="d-flex justify-content-between"><a href="<?= e(app_url('student/course.php?id=' . $course['id'])) ?>"><?= e($course['title']) ?></a><span><?= $progress ?>%</span></div><div class="progress"><div class="progress-bar" style="width: <?= $progress ?>%"></div></div></div><?php endforeach; ?></div></div></div>
<?php require __DIR__ . '/../includes/footer.php'; ?>
